    "intervention": "Khuyến cáo đồng thuận quốc gia toàn diện năm 2026 giữa VUNA và VNUA về chẩn đoán và điều trị tăng kali máu: Phân loại 3 mức độ (Nhẹ 5.0-5.9, Trung bình 6.0-6.4, Nặng ≥ 6.5 hoặc có biến đổi điện tim); Phân biệt tăng kali máu giả (tan máu cơ học, tăng tiểu cầu, tăng bạch cầu, sai mẫu K-EDTA) vs thực sự; Hệ thống hóa 6 giai đoạn biến đổi ECG tiến triển; Triển khai đồng thời Kiềng ba chân cấp cứu: (1) Ổn định màng cơ tim tức thì bằng Calci Clorua 10% 10ml hoặc Calci Gluconat 10% 30ml tiêm TM; (2) Dịch chuyển kali vào nội bào bằng Insulin Regular 10 UI + Glucose 25g (kèm phác đồ truyền G10% 50ml/h x 5h chống hạ đường huyết nếu đường nền < 7.0 mmol/L), phối hợp khí dung Salbutamol liều cao 10-20mg và NaHCO3 1.4% khi toan nặng pH < 7.10; (3) Đào thải triệt để bằng Thận nhân tạo ngắt quãng cấp cứu (HD - lưu ý hiện tượng hồi ứng kali sau lọc 35% sau 1h và 70% sau 6h), CRRT cho bệnh nhân sốc, Lợi tiểu quai Furosemide 40-80mg khi còn tiểu, và Thuốc gắn kali đường tiêu hóa thế hệ mới (SZC 10g x 3 lần/ngày hoặc Patiromer 8.4g/ngày; hạn chế dùng SPS do nguy cơ hoại tử ruột); Hai lưu đồ phân tầng xử trí cấp cứu toàn diện và bệnh nhân thận mạn giai đoạn 5; Chiến lược bảo tồn và không vội vã ngừng vĩnh viễn thuốc ức chế hệ RASi (ACEi, ARB, MRA) ở bệnh nhân suy tim và CKD nhờ phối hợp thuốc gắn kali mới dài hạn.",
