    "keyResults": "Ổn định màng tim bằng Calci tĩnh mạch ngay lập tức khi K+ ≥ 6.5 mmol/L hoặc có biến đổi ECG | Insulin 10 UI + Glucose 25g kèm Salbutamol 10-20mg khí dung giúp hạ kali 1.0 - 1.5 mmol/L sau 30-60 phút | HD là biện pháp đào thải nhanh nhất (hạ > 1.0 mmol/L trong giờ đầu) nhưng cần cảnh giác hiện tượng kali hồi ứng 70% sau 6h | Thuốc gắn kali thế hệ mới SZC (tác dụng sau 1h) và Patiromer thay thế SPS an toàn, không gây hoại tử ruột | Không vội ngừng vĩnh viễn thuốc RASi mà chủ động phối hợp thuốc gắn kali mới để duy trì lợi ích tim thận.",
    "summary": "Đồng thuận quốc gia toàn diện năm 2026 giữa Hội Hồi sức Cấp cứu & Chống độc VN (VUNA) và Hội Tiết niệu - Thận học VN (VNUA): Cập nhật sinh lý chuyển hóa kali, 6 giai đoạn ECG, kiềng ba chân điều trị cấp cứu (Calci, Insulin-Glucose, Salbutamol, HD/CRRT, SZC/Patiromer), 2 lưu đồ xử trí cấp cứu & CKD gđ 5, và chiến lược bảo tồn thuốc RASi.",
    "detailedConclusion": "Bác sĩ cấp cứu và hồi sức đánh giá ngay ABCDE và ECG ở bệnh nhân tăng kali máu. Nếu có biến đổi ECG hoặc K+ ≥ 6.5 mmol/L, tiêm ngay Calci tĩnh mạch để bảo vệ tim, đồng thời kích hoạt Insulin-Glucose và Salbutamol khí dung. Chỉ định lọc máu cấp cứu (HD/CRRT) khi có vô niệu, quá tải dịch, toan máu trơ hoặc K+ trơ nội khoa. Ở bệnh nhân suy tim và CKD, không ngừng vĩnh viễn thuốc RASi mà phối hợp thuốc gắn kali mới (SZC hoặc Patiromer) để kiểm soát kali máu ổn định lâu dài.",
