    "population": "Người trưởng thành (≥18 tuổi) cần phòng ngừa, tầm soát, chẩn đoán và quản lý tăng huyết áp, bao gồm cả các nhóm đối tượng có bệnh lý tim mạch, bệnh thận mạn, đái tháo đường đồng mắc hoặc phụ nữ trong thai kỳ.",
    "asianData": true,
    "subgroups": "{\"Phân tầng khởi trị thuốc hạ áp theo nguy cơ tim mạch\":\"Khởi trị khi BP ≥140/90 mmHg ở mọi đối tượng | Khởi trị khi BP ≥130/80 mmHg kèm CVD, CKD, đái tháo đường, hoặc nguy cơ tim mạch 10 năm ≥7.5% (PREVENT)\",\"Hiệu quả hạ áp tâm thu (SBP) của can thiệp lối sống\":\"COL: Chế độ ăn DASH: -11 mmHg | Giảm natri (<2300 mg/ngày): -5 đến -6 mmHg | Tập thể dục hiếu khí (Aerobic): -5 đến -8 mmHg | Hạn chế rượu bia (Goal ≤1-2 drinks/ngày): -4 mmHg\",\"Định nghĩa các phân độ huyết áp động mạch\":\"HBAR: Huyết áp bình thường: <120/<80 mmHg | Huyết áp tăng vọt (Elevated): 120-129/<80 mmHg | Tăng huyết áp giai đoạn 1 (Stage 1): 130-139 hoặc 80-89 mmHg\"}",
