    "primaryEndpoint": "Ngăn ngừa đợt mất bù đầu tiên, giảm thất bại cầm máu 5 ngày và tử vong 6 tuần trong xuất huyết cấp, ngăn ngừa tái xuất huyết và cải thiện sống còn toàn bộ",
    "keyResults": "Carvedilol giảm HVPG và nguy cơ cổ trướng vượt trội; Tiêu chuẩn Baveno VI bỏ sót < 5% giãn nguy cơ cao; Preemptive TIPS giảm tử vong rõ rệt ở Child C và Child B có chảy máu; Phối hợp NSBB + EVL là tiêu chuẩn vàng dự phòng thứ phát.",
    "summary": "Hướng dẫn thực hành lâm sàng toàn diện của AASLD 2024: Chuyển dịch mô hình tiếp cận cACLD/CSPH, cơ chế kép Carvedilol, quy chuẩn 12 bước đo HVPG, lưu đồ cấp cứu AVH (Figure 4), chỉ định TIPS chủ động, tiêu chuẩn lựa chọn TIPS vs BRTO và thang điểm Baveno III PHG.",
    "detailedConclusion": "Khởi trị sớm Carvedilol ngay khi xác định có CSPH không xâm lấn; không cần nội soi dạ dày sàng lọc ở bệnh nhân đã dùng NSBB hoặc thỏa Baveno VI; kích hoạt Preemptive TIPS trong 24-72h cho bệnh nhân xuất huyết cấp nguy cơ cao.",
    "drug": "Carvedilol, Propranolol, Nadolol, Somatostatin, Octreotide, Terlipressin, Ceftriaxone, Erythromycin, Simvastatin, Atorvastatin, Metformin, Aspirin, Lactulose, Rifaximin",
