    "keyResults": "HBAR: MELD > 20: Severe AH (Tử vong 90d ~ 20%) | Lille <= 0.45: Đáp ứng tiếp tục 28d | Prednisolone + IV NAC 5d: Giảm 85% tử vong AH | Sống sót 3 năm Ghép gan sớm (ACCELERATE-AH): 84% (vs 24% không ghép) | Thiếu Kẽm: Tăng 10.6x tử vong",
    "summary": "Hướng dẫn thực hành lâm sàng toàn diện của ACG về ALD và Viêm gan do rượu (AH): Tiêu chuẩn NIAAA chẩn đoán không cần sinh thiết cho Probable AH, phân tầng MELD, cửa sổ trị liệu Corticosteroids (MELD 21-39), dừng thuốc theo Lille Score, điều trị AUD bằng Baclofen và chỉ định Ghép gan sớm bỏ quy tắc 6 tháng.",
    "detailedConclusion": "MELD > 20 là chỉ định điều trị Prednisolone kết hợp IV NAC. Bắt buộc tính Lille score ngày 4 hoặc 7 để dừng ngay steroids nếu không đáp ứng nhằm tránh tử vong do nấm xâm lấn. Bệnh nhân không đáp ứng nội khoa cần được đánh giá Ghép gan sớm.",
