    "keyResults": "HBAR: LFI tăng mỗi 0.1 điểm: HR 2.04 | Tử vong chờ ghép theo LFI: HR 1.82 | SMI chẩn đoán sarcopenia: Nam <50, Nữ <39 cm2/m2 | Nhu cầu năng lượng: 35 kcal/kg/ngày",
