    "conditionKey": "diphtheria",
    "icd10": [
      "A36",
      "A36.0",
      "A36.9"
    ],
    "intervention": "Quy chuẩn chẩn đoán & điều trị toàn diện bệnh bạch hầu theo QĐ 2957/QĐ-BYT; 4 nguyên tắc điều trị cốt lõi; Đặc điểm vi sinh Corynebacterium diphtheriae; Tiêu chuẩn chẩn đoán 4 thể bệnh (họng, ác tính cổ bạnh bull-neck, thanh quản, mũi/mắt/da); Lưu đồ chẩn đoán phân biệt với viêm amidan hốc mủ và croup; Tiêu chuẩn cận lâm sàng: nhuộm soi, nuôi cấy Loeffler/CTBA, Elek test và PCR gen tox; Phác đồ phân liều Huyết thanh kháng độc tố bạch hầu (SAD 20.000 – 100.000 UI) dùng ngay khi nghi ngờ lâm sàng; Quy trình test mẫn cảm da Besredka 3 bước và giải mẫn cảm; Liệu pháp kháng sinh 14 ngày (Penicillin G tiêm bắp, Erythromycin, Azithromycin); Chỉ định mở khí quản khẩn cấp khi khó thở thanh quản từ độ II; Hồi sức tuần hoàn sốc nhiễm độc (CVP 12-14 cmH2O); Đặt máy tạo nhịp tạm thời (Pacemaker) cho Block AV độ II/III và chỉ định VA-ECMO cho sốc tim trơ; 5 tiêu chuẩn xuất viện khắt khe (cấy âm tính 2 lần, bắt buộc tiêm vắc-xin sau xuất viện, theo dõi ngoại trú 70 ngày); Cách ly kiểm soát nhiễm khuẩn và phác đồ hóa dự phòng 7 ngày (Benzathine Penicillin G hoặc Macrolide) cho người tiếp xúc gần.",
    "primaryEndpoint": "Chuẩn hóa quy trình phát hiện sớm và cách ly ca bệnh bạch hầu, chỉ định kịp thời liệu pháp trung hòa độc tố SAD và kháng sinh diệt khuẩn, can thiệp mở khí quản và hỗ trợ tuần hoàn chuyên sâu nhằm giảm thiểu tối đa tỷ lệ tử vong do ngạt thở và viêm cơ tim nhiễm độc.",
    "keyResults": "Chỉ định SAD và Kháng sinh đồng thời NGAY LẬP TỨC khi nghi ngờ lâm sàng | Phân liều SAD theo thể lâm sàng: 20k-40k UI (nhẹ ≤ 2 ngày), 40k-60k UI (mũi họng), 80k-100k UI (ác tính cổ bạnh) | Bắt buộc test da Besredka 3 bước trước khi tiêm SAD | Mở khí quản khẩn cấp khi khó thở thanh quản từ độ II trở lên | Đặt máy tạo nhịp tạm thời cho Block AV độ II/III và cân nhắc VA-ECMO cho sốc tim trơ | Bắt buộc tiêm vắc-xin bạch hầu sau khi xuất viện vì miễn dịch tự nhiên không bền vững | Hóa dự phòng 7 ngày cho 100% người tiếp xúc gần.",
    "summary": "Hướng dẫn chuyên môn toàn diện ban hành theo Quyết định số 2957/QĐ-BYT ngày 10/07/2020 của Bộ Y tế: Tích hợp đầy đủ lưu đồ chẩn đoán phân biệt màng giả, bảng phân liều SAD, quy trình test mẫn cảm Besredka 3 bước, chỉ định can thiệp mở khí quản, hồi sức viêm cơ tim/Pacemaker/VA-ECMO, tiêu chuẩn xuất viện và phác đồ hóa dự phòng 7 ngày cho cộng đồng.",
    "detailedConclusion": "Bác sĩ lâm sàng phát hiện sớm ca nghi ngờ bạch hầu (giả mạc dai dính, bóc chảy máu, không tan trong nước) và cách ly ngay. Khởi động đồng thời SAD (theo test Besredka) và kháng sinh trong 14 ngày không đợi xét nghiệm. Giám sát sát sao đường thở để mở khí quản kịp thời khi khó thở độ II; theo dõi điện tim để đặt Pacemaker/ECMO khi có viêm cơ tim. Bắt buộc tiêm vắc-xin sau xuất viện và cấp kháng sinh hóa dự phòng 7 ngày cho toàn bộ người tiếp xúc gần.",
    "drug": "Huyết thanh kháng độc tố bạch hầu (SAD), Penicillin G, Erythromycin, Azithromycin, Corticoid, Adrenaline, Noradrenaline, Oxygen",
    "sampleSize": 4553,
    "population": "Trẻ em và người lớn nghi ngờ hoặc xác định mắc bệnh bạch hầu hoặc có tiền sử tiếp xúc gần với ca bệnh trong vòng 7 ngày.",
    "asianData": true,
