    "intervention": "Phác đồ chuẩn 4 thuốc kháng lao hàng một (Rifampicin, Isoniazid, Pyrazinamide, Ethambutol/Streptomycin) phối hợp Corticosteroid hỗ trợ; Phân tích gộp 39 nghiên cứu với 5.752 bệnh nhân người lớn; Xác định động học tử vong sớm (> 90% tử vong xảy ra trong 3 tháng đầu); Nguy cơ tử vong tăng vọt 3.5 lần ở người đồng nhiễm HIV (57% so với 16%); Lượng giá di chứng tàn tật thần kinh ở 32% người sống sót (mRS > 2 đạt 26%, Barthel < 80 đạt 32%); Đồng thuận quốc tế bắt buộc dùng thang điểm Rankin cải tiến (mRS) tại mốc 12 tháng.",
    "primaryEndpoint": "Đánh giá tỷ lệ tử vong gộp, động học tử vong theo thời gian và tỷ lệ di chứng tàn tật thần kinh ở người trưởng thành bị lao màng não trên toàn cầu.",
    "keyResults": "Tỷ lệ tử vong gộp chung 24% | > 90% tử vong tập trung trong 3 tháng đầu (23% tại mốc 3 tháng) | Tỷ lệ tử vong ở người đồng nhiễm HIV lên tới 57% (so với 16% không nhiễm HIV, P < 0.001) | Tỷ lệ tàn tật thần kinh ở người sống sót đạt 32% | Không có sự cải thiện sống còn trong suốt hơn 20 năm qua.",
    "summary": "Tổng quan hệ thống và phân tích gộp lớn nhất của IDSA/OFID về kết cục điều trị lao màng não ở 5.752 người lớn từ 39 nghiên cứu: Xác định tỷ lệ tử vong 24%, tập trung > 90% trong 3 tháng đầu, nguy cơ tử vong tăng gấp 3.5 lần ở nhóm HIV (57% vs 16%), 32% người sống sót bị tàn tật thần kinh vĩnh viễn, và đồng thuận quốc tế chuẩn hóa đo lường mRS tại mốc 12 tháng.",
