    "summary": "Hướng dẫn thực hành lâm sàng toàn cầu kinh điển của WSES (Sartelli et al., WJES 2017): Tích hợp định nghĩa Sepsis-3, thang điểm SOFA/qSOFA, lưu đồ phân tầng ALCD trực quan hóa, phẫu thuật kiểm soát nguồn nhiễm cho 7 bệnh cảnh ngoại khoa, chiến lược mổ lại On-demand, kỹ thuật bụng mở NPT, thời gian kháng sinh 3-5 ngày và 4 phụ lục kháng sinh chi tiết.",
    "detailedConclusion": "Phẫu thuật viên và bác sĩ cấp cứu ưu tiên kiểm soát nguồn nhiễm khẩn cấp. Áp dụng chuẩn 3 - 5 ngày kháng sinh sau khi kiểm soát nguồn nhiễm tốt. Nghi ngờ sốc nhiễm trùng khi MAP < 65 và Lactate > 2 mmol/L. Chọn Norepinephrine làm vận mạch số 1.",
